export const envelope = [32, 28, 36];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 6;
  const cx = 15.5;

  // Theme roles with safe standard fallbacks
  const pStone = api.theme.stone.primary || "minecraft:smooth_sandstone";
  const pAccent = api.theme.stone.accent || "minecraft:cut_sandstone";
  const pPlinth = api.theme.ground.plinth || "minecraft:sandstone";
  const pPavement = api.theme.ground.pavement || "minecraft:smooth_sandstone";
  const pKerb = api.theme.ground.kerb || "minecraft:cut_sandstone";
  const pStairs = api.theme.stone.stairs || "minecraft:sandstone_stairs";
  const pSlab = api.theme.stone.slab || "minecraft:sandstone_slab";
  const pWall = api.theme.stone.wall || "minecraft:sandstone_wall";
  const pWoodPlanks = api.theme.wood.planks || "minecraft:oak_planks";
  const pWoodFence = api.theme.wood.fence || "minecraft:oak_fence";

  // State formatting helpers
  function makeStair(baseStr, facing, half = "bottom", shape = "straight") {
    const baseName = (baseStr || "minecraft:sandstone_stairs").split("[")[0];
    return `${baseName}[facing=${facing},half=${half},shape=${shape},waterlogged=false]`;
  }

  function makeSlab(baseStr, type = "bottom") {
    const baseName = (baseStr || "minecraft:sandstone_slab").split("[")[0];
    return `${baseName}[type=${type},waterlogged=false]`;
  }

  function getBone(axis = "y", seed = 0) {
    const v = Math.sin(seed * 12.9898) * 43758.5453;
    const frac = v - Math.floor(v);
    if (frac > 0.88) return "minecraft:smooth_sandstone";
    if (frac > 0.80) return "minecraft:cut_sandstone";
    return `minecraft:bone_block[axis=${axis}]`;
  }

  // 3D Voxel buffer
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Array(D).fill(null))
  );

  function setV(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = block;
    }
  }

  function getV(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[x][y][z];
    }
    return null;
  }

  // -------------------------------------------------------------
  // 1. TEMPLE FLOORING & ENTRANCE STEPS
  // -------------------------------------------------------------
  // Entrance steps at z = 0..3 stepping from seatY up to seatY + 2
  for (let x = 12; x <= 19; x++) {
    setV(x, seatY, 0, makeStair(pStairs, "north"));
  }
  for (let x = 11; x <= 20; x++) {
    setV(x, seatY, 1, pStone);
    if (x >= 12 && x <= 19) setV(x, seatY + 1, 1, makeStair(pStairs, "north"));
  }
  for (let x = 10; x <= 21; x++) {
    setV(x, seatY, 2, pStone);
    setV(x, seatY + 1, 2, pStone);
    if (x >= 12 && x <= 19) setV(x, seatY + 2, 2, makeStair(pStairs, "north"));
  }

  // Main temple floor at y = seatY + 2 (z = 3 to 34)
  for (let z = 3; z <= 34; z++) {
    let flW;
    if (z <= 13) {
      flW = 4.0 + (z / 14.0) * 6.5;
    } else if (z <= 32) {
      const u = (z - 13) / 19.0;
      flW = 12.0 * Math.pow(Math.sin(u * Math.PI), 0.5) + 3.0;
    } else {
      flW = 4.0;
    }

    const minX = Math.max(1, Math.floor(cx - flW));
    const maxX = Math.min(W - 2, Math.ceil(cx + flW));

    for (let x = minX; x <= maxX; x++) {
      // Sub-floor solid plinth
      setV(x, seatY + 1, z, pPlinth);

      // Floor surface
      if (x >= 14 && x <= 17) {
        // Central ritual runner
        setV(x, seatY + 2, z, (z % 3 === 0) ? pAccent : pPavement);
      } else if (x === 13 || x === 18) {
        setV(x, seatY + 2, z, pKerb);
      } else {
        setV(x, seatY + 2, z, pPavement);
      }
    }
  }

  // Sanctuary Raised Dais (z = 25 to 31, y = seatY + 3)
  for (let x = 12; x <= 19; x++) {
    setV(x, seatY + 3, 25, makeStair(pStairs, "north"));
  }
  for (let z = 26; z <= 31; z++) {
    for (let x = 10; x <= 21; x++) {
      setV(x, seatY + 2, z, pStone);
      setV(x, seatY + 3, z, (x >= 14 && x <= 17) ? pAccent : pPavement);
    }
  }

  // -------------------------------------------------------------
  // 2. CRANIUM VAULTED DOME (z = 13 to 34)
  // -------------------------------------------------------------
  const cranCenterZ = 23.5;
  const cranCenterY = seatY + 8.5;

  for (let z = 13; z <= 34; z++) {
    const u = (z - 13) / 21.0;
    const profile = Math.sin(u * Math.PI);
    const rxOut = 13.2 * Math.pow(profile, 0.48) + 2.4;
    const ryOut = 10.8 * Math.pow(profile, 0.45) + 2.0;

    const rxIn = Math.max(1.2, rxOut - 1.8);
    const ryIn = Math.max(1.2, ryOut - 1.6);

    for (let x = 0; x < W; x++) {
      const dx = x - cx;
      for (let y = seatY + 2; y < H; y++) {
        const dy = y - cranCenterY;

        const dOut = (dx / rxOut) ** 2 + (dy / ryOut) ** 2;
        const dIn = (dx / rxIn) ** 2 + (dy / ryIn) ** 2;

        if (dOut <= 1.0 && dIn >= 1.0) {
          // Check Blowhole Skylight Openings (z = 21..24, dorsal top)
          const isBlowhole = (y >= seatY + 14) && (z >= 21 && z <= 24) &&
            ((x === 13 || x === 14 || x === 17 || x === 18) && (z === 22 || z === 23));

          // Check Eye Socket Openings (z = 13..17, lateral flanks)
          const isLeftEye = (x <= 7) && (z >= 13 && z <= 17) && (y >= seatY + 3 && y <= seatY + 8) &&
            (((z - 15) / 2.3) ** 2 + ((y - (seatY + 5.5)) / 2.6) ** 2 <= 1.0);
          const isRightEye = (x >= 24) && (z >= 13 && z <= 17) && (y >= seatY + 3 && y <= seatY + 8) &&
            (((z - 15) / 2.3) ** 2 + ((y - (seatY + 5.5)) / 2.6) ** 2 <= 1.0);

          if (!isBlowhole && !isLeftEye && !isRightEye) {
            setV(x, y, z, getBone("z", x * 17 + y * 31 + z * 7));
          }
        }
      }
    }

    // Sagittal dorsal crest along cranial midline
    const topY = Math.min(H - 1, Math.floor(cranCenterY + ryOut));
    setV(15, topY, z, getBone("z", z * 11));
    setV(16, topY, z, getBone("z", z * 13));
  }

  // Eye Socket Balconies & Overlooks
  for (let z = 13; z <= 17; z++) {
    // Left balcony
    for (let x = 4; x <= 8; x++) {
      setV(x, seatY + 2, z, pPlinth);
      setV(x, seatY + 3, z, pWoodPlanks);
    }
    setV(4, seatY + 4, z, pWoodFence);

    // Right balcony
    for (let x = 23; x <= 27; x++) {
      setV(x, seatY + 2, z, pPlinth);
      setV(x, seatY + 3, z, pWoodPlanks);
    }
    setV(27, seatY + 4, z, pWoodFence);
  }

  // Blowhole Skylight Rims
  for (let z = 21; z <= 24; z++) {
    for (let x = 12; x <= 19; x++) {
      if ((x >= 13 && x <= 14) || (x >= 17 && x <= 18)) {
        if (z === 21 || z === 24 || x === 12 || x === 19) {
          const by = seatY + 16;
          if (getV(x, by, z) === null) {
            setV(x, by, z, makeSlab(pSlab, "bottom"));
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 3. ROSTRUM / UPPER SNOUT VAULT (z = 0 to 13)
  // -------------------------------------------------------------
  for (let z = 0; z <= 13; z++) {
    const u = z / 14.0;
    const yTop = seatY + 6.5 + u * 9.0;
    const wOut = 4.2 + u * 7.5;
    const wIn = Math.max(1.0, wOut - 1.6);

    for (let x = 0; x < W; x++) {
      const dx = Math.abs(x - cx);
      if (dx <= wOut) {
        const yVaultOut = yTop - ((dx / wOut) ** 1.65) * (yTop - (seatY + 2.0));
        const yVaultIn = (yTop - 1.4) - ((dx / wIn) ** 1.65) * (yTop - (seatY + 3.2));

        for (let y = seatY + 2; y <= Math.ceil(yTop); y++) {
          if (y <= yVaultOut && (y >= yVaultIn || y <= seatY + 2)) {
            setV(x, y, z, getBone("z", x * 13 + y * 7 + z * 23));
          }
        }
      }
    }

    // Rostrum dorsal ridge
    const ridgeY = Math.min(H - 1, Math.floor(yTop) + 1);
    setV(15, ridgeY, z, getBone("z", z * 19));
    setV(16, ridgeY, z, getBone("z", z * 23));
  }

  // -------------------------------------------------------------
  // 4. BALEEN / TOOTH ARCHES (PORTICO COLONNADE)
  // -------------------------------------------------------------
  const toothStations = [2, 4, 6, 8, 10, 12];
  for (const tz of toothStations) {
    const u = tz / 14.0;
    const wSnout = 4.2 + u * 7.5;
    const yRim = Math.floor(seatY + 6.5 + u * 9.0 - (wSnout / wSnout) ** 1.65 * (4.5 + u * 9.0));

    const leftX = Math.round(cx - wSnout);
    const rightX = Math.round(cx + wSnout);

    // Left tooth pillar
    for (let y = seatY + 1; y <= yRim + 1; y++) {
      setV(leftX, y, tz, getBone("y", leftX * 3 + y * 7));
      setV(leftX, y, tz + 1, getBone("y", leftX * 5 + y * 11));
    }
    setV(leftX + 1, seatY + 1, tz, makeStair(pStairs, "west", "bottom"));
    setV(leftX + 1, yRim, tz, makeStair(pStairs, "east", "top"));

    // Right tooth pillar
    for (let y = seatY + 1; y <= yRim + 1; y++) {
      setV(rightX, y, tz, getBone("y", rightX * 3 + y * 7));
      setV(rightX, y, tz + 1, getBone("y", rightX * 5 + y * 11));
    }
    setV(rightX - 1, seatY + 1, tz, makeStair(pStairs, "east", "bottom"));
    setV(rightX - 1, yRim, tz, makeStair(pStairs, "west", "top"));
  }

  // -------------------------------------------------------------
  // 5. LOWER MANDIBLES (SWEEPING JAWBONES)
  // -------------------------------------------------------------
  for (let z = 0; z <= 18; z++) {
    const u = z / 18.0;
    const mandXLeft = 7.0 - Math.sin(u * Math.PI * 0.75) * 4.6;
    const mandXRight = 31.0 - mandXLeft;
    const mandY = seatY + 1.0 + u * 6.5;

    const mxL = Math.round(mandXLeft);
    const mxR = Math.round(mandXRight);
    const my = Math.round(mandY);

    // Left jaw cross-section
    setV(mxL, my, z, getBone("z", z * 17));
    setV(mxL + 1, my, z, getBone("z", z * 19));
    setV(mxL, my - 1, z, getBone("z", z * 23));
    setV(mxL + 1, my - 1, z, pStone);

    // Right jaw cross-section
    setV(mxR, my, z, getBone("z", z * 29));
    setV(mxR - 1, my, z, getBone("z", z * 31));
    setV(mxR, my - 1, z, getBone("z", z * 37));
    setV(mxR - 1, my - 1, z, pStone);
  }

  // -------------------------------------------------------------
  // 6. INTERNAL TRANSVERSE VAULT RIBS
  // -------------------------------------------------------------
  const ribStations = [8, 13, 18, 23, 28];
  for (const rz of ribStations) {
    for (let x = 4; x <= 27; x++) {
      for (let y = seatY + 4; y < H - 1; y++) {
        if (getV(x, y, rz) === null && getV(x, y + 1, rz) !== null) {
          // Protruding rib voxel under ceiling
          setV(x, y, rz, getBone("x", x * 13 + y * 7));
          break;
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 7. SANCTUARY HIGH ALTAR & RELIQUARY
  // -------------------------------------------------------------
  // Altar Base (z = 27 to 29, x = 14 to 17)
  for (let z = 27; z <= 29; z++) {
    for (let x = 14; x <= 17; x++) {
      setV(x, seatY + 3, z, pStone);
      setV(x, seatY + 4, z, (x === 14 || x === 17) ? getBone("y", x + z) : pAccent);
    }
  }

  // Altar Table & Reliquary centerpiece
  setV(14, seatY + 5, 27, makeSlab(pSlab, "bottom"));
  setV(17, seatY + 5, 27, makeSlab(pSlab, "bottom"));
  setV(14, seatY + 5, 29, makeSlab(pSlab, "bottom"));
  setV(17, seatY + 5, 29, makeSlab(pSlab, "bottom"));
  setV(15, seatY + 5, 27, pKerb);
  setV(16, seatY + 5, 27, pKerb);
  setV(15, seatY + 5, 29, pKerb);
  setV(16, seatY + 5, 29, pKerb);

  // Sacred Altar Braziers (Soul Fire)
  setV(14, seatY + 5, 28, "minecraft:soul_campfire[lit=true]");
  setV(17, seatY + 5, 28, "minecraft:soul_campfire[lit=true]");

  // Central Sacred Relic
  setV(15, seatY + 5, 28, "minecraft:chiseled_sandstone");
  setV(16, seatY + 5, 28, "minecraft:chiseled_sandstone");
  setV(15, seatY + 6, 28, "minecraft:sea_lantern");
  setV(16, seatY + 6, 28, "minecraft:sea_lantern");

  // Altar Reredos Backdrop (z = 31, x = 13..18)
  for (let x = 13; x <= 18; x++) {
    for (let y = seatY + 4; y <= seatY + 8; y++) {
      if (x === 13 || x === 18) {
        setV(x, y, 31, getBone("y", x * 5 + y * 7));
      } else {
        setV(x, y, 31, (y === seatY + 8) ? makeSlab(pSlab, "top") : pAccent);
      }
    }
  }

  // -------------------------------------------------------------
  // 8. OCCIPITAL CONDYLES & SPINAL ARCHWAY (z = 32 to 35)
  // -------------------------------------------------------------
  const occY = seatY + 6.5;
  for (let z = 32; z <= 35; z++) {
    for (let x = 9; x <= 22; x++) {
      for (let y = seatY + 2; y <= seatY + 12; y++) {
        const dx = x - cx;
        const dy = y - occY;
        const d = Math.sqrt(dx * dx + dy * dy);

        if (d <= 5.4 && d >= 3.2) {
          setV(x, y, z, getBone("z", x * 7 + y * 13 + z * 19));
        }
      }
    }
  }

  // Dual Occipital Condyle rounded masses
  for (let z = 34; z <= 35; z++) {
    for (let y = seatY + 3; y <= seatY + 6; y++) {
      for (let x = 9; x <= 11; x++) setV(x, y, z, getBone("z", x + y));
      for (let x = 20; x <= 22; x++) setV(x, y, z, getBone("z", x + y));
    }
  }

  // -------------------------------------------------------------
  // 9. HANGING CHAINS, LANTERNS & BRAZIERS
  // -------------------------------------------------------------
  // Nave & Sanctuary Hanging Lanterns
  const lanternDrops = [
    { x: 15, z: 8, topY: seatY + 9, len: 2, soul: false },
    { x: 16, z: 8, topY: seatY + 9, len: 2, soul: false },
    { x: 15, z: 13, topY: seatY + 12, len: 3, soul: false },
    { x: 16, z: 13, topY: seatY + 12, len: 3, soul: false },
    { x: 15, z: 18, topY: seatY + 14, len: 3, soul: true },
    { x: 16, z: 18, topY: seatY + 14, len: 3, soul: true },
    { x: 15, z: 28, topY: seatY + 13, len: 4, soul: true },
    { x: 16, z: 28, topY: seatY + 13, len: 4, soul: true },
    { x: 5, z: 15, topY: seatY + 7, len: 2, soul: false },
    { x: 26, z: 15, topY: seatY + 7, len: 2, soul: false },
  ];

  for (const l of lanternDrops) {
    for (let i = 0; i < l.len; i++) {
      setV(l.x, l.topY - i, l.z, "minecraft:chain[axis=y]");
    }
    const lanternBlock = l.soul
      ? "minecraft:soul_lantern[hanging=true]"
      : "minecraft:lantern[hanging=true]";
    setV(l.x, l.topY - l.len, l.z, lanternBlock);
  }

  // Entrance Flanking Pilgrimage Braziers
  setV(9, seatY + 1, 1, pPlinth);
  setV(9, seatY + 2, 1, pKerb);
  setV(9, seatY + 3, 1, "minecraft:campfire[lit=true]");

  setV(22, seatY + 1, 1, pPlinth);
  setV(22, seatY + 2, 1, pKerb);
  setV(22, seatY + 3, 1, "minecraft:campfire[lit=true]");

  // -------------------------------------------------------------
  // 10. GROUND CONFORMANCE & EMISSION TO API
  // -------------------------------------------------------------
  // Read heightAt at every occupied column and extend foundations down
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      let lowestY = -1;
      let lowestBlock = null;

      for (let y = 0; y < H; y++) {
        if (grid[x][y][z] !== null) {
          lowestY = y;
          lowestBlock = grid[x][y][z];
          break;
        }
      }

      if (lowestY !== -1) {
        // Column is occupied: check terrain height
        const terrainH = Math.round(api.heightAt(x, z));
        const targetGroundY = Math.max(0, Math.min(H - 1, seatY + terrainH));

        // Choose continuous foundation material
        let fillBlock = pPlinth;
        if (lowestBlock.includes("bone_block")) {
          fillBlock = getBone("y", x * 11 + z * 17);
        } else if (lowestBlock.includes("pavement") || lowestBlock.includes("stone")) {
          fillBlock = pStone;
        }

        // Extend downwards if ground falls away
        if (targetGroundY < lowestY) {
          for (let y = lowestY - 1; y >= targetGroundY; y--) {
            grid[x][y][z] = fillBlock;
          }
        }
      }
    }
  }

  // Emit all voxels into world
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = grid[x][y][z];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "skywhale_skull_temple",
    seatY: seatY,
    anchors: {
      front: [16, seatY, 0],
      door: [16, seatY + 2, 0],
      altar: [16, seatY + 4, 28],
      spine: [16, seatY + 2, 35]
    },
    interiors: [
      { min: [10, seatY + 3, 4], max: [21, seatY + 10, 24], kind: "nave" },
      { min: [11, seatY + 4, 25], max: [20, seatY + 11, 31], kind: "vault" },
      { min: [4, seatY + 4, 13], max: [8, seatY + 7, 17], kind: "hall" },
      { min: [23, seatY + 4, 13], max: [27, seatY + 7, 17], kind: "hall" }
    ]
  };
}

