export const envelope = [27, 20, 48];

export default function build(api) {
  const [W, H, D] = api.size;

  // Theme-aware palette extraction with robust fallbacks
  const woodPlanks = api.theme?.wood?.planks ?? "minecraft:oak_planks";
  const woodLog = api.theme?.wood?.log ?? "minecraft:oak_log";
  const woodStripped = api.theme?.wood?.stripped ?? "minecraft:stripped_oak_log";
  const woodStairs = api.theme?.wood?.stairs ?? "minecraft:oak_stairs";
  const woodSlab = api.theme?.wood?.slab ?? "minecraft:oak_slab";
  const woodFence = api.theme?.wood?.fence ?? "minecraft:oak_fence";
  const woodTrapdoor = api.theme?.wood?.trapdoor ?? "minecraft:oak_trapdoor";

  const stonePrimary = api.theme?.stone?.primary ?? "minecraft:cut_sandstone";
  const stoneAccent = api.theme?.stone?.accent ?? "minecraft:chiseled_sandstone";
  const stoneStairs = api.theme?.stone?.stairs ?? "minecraft:sandstone_stairs";
  const stoneSlab = api.theme?.stone?.slab ?? "minecraft:sandstone_slab";
  const stoneWall = api.theme?.stone?.wall ?? "minecraft:sandstone_wall";

  const groundPave = api.theme?.ground?.pavement ?? "minecraft:smooth_sandstone";
  const groundKerb = api.theme?.ground?.kerb ?? "minecraft:cut_sandstone";
  const groundPlinth = api.theme?.ground?.plinth ?? "minecraft:sandstone";
  const groundRev = api.theme?.ground?.revetment ?? "minecraft:cut_sandstone";

  function withState(blockStr, stateStr) {
    if (!blockStr) return blockStr;
    if (blockStr.includes("[")) {
      const base = blockStr.split("[")[0];
      const existing = blockStr.slice(blockStr.indexOf("[") + 1, -1);
      return `${base}[${existing},${stateStr}]`;
    }
    return `${blockStr}[${stateStr}]`;
  }

  function setBlock(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  // ==========================================
  // 1. TERRAIN CONFORMATION & GROUND PLINTH
  // ==========================================
  for (let x = 1; x <= 25; x++) {
    for (let z = 0; z < D; z++) {
      const h = Math.floor(api.heightAt(x, z));
      const minGround = Math.min(0, h);

      // Foundation down to real terrain
      for (let y = minGround; y < 0; y++) {
        if (x <= 2 || x >= 24 || z === 0 || z === D - 1) {
          setBlock(x, y, z, groundRev);
        } else {
          setBlock(x, y, z, groundPlinth);
        }
      }

      // Ground pavement course at y = 0
      if (x >= 9 && x <= 17) {
        // Main vertebral avenue
        if (x === 13) {
          if (z % 3 === 0) {
            setBlock(x, 0, z, "minecraft:bone_block[axis=z]");
          } else {
            setBlock(x, 0, z, groundKerb);
          }
        } else if (x === 9 || x === 17) {
          setBlock(x, 0, z, groundKerb);
        } else {
          setBlock(x, 0, z, groundPave);
        }
      } else if ((x >= 2 && x <= 8) || (x >= 18 && x <= 24)) {
        // Bazaar stall floors
        setBlock(x, 0, z, woodPlanks);
      }
    }
  }

  // ==========================================
  // 2. DORSAL VERTEBRAL SPINE (Apex along Z)
  // ==========================================
  for (let z = 0; z < D; z++) {
    // Neural canal and vertebral body
    setBlock(13, 16, z, "minecraft:bone_block[axis=z]");
    setBlock(12, 16, z, "minecraft:bone_block[axis=x]");
    setBlock(14, 16, z, "minecraft:bone_block[axis=x]");
    setBlock(13, 15, z, "minecraft:bone_block[axis=y]");
    setBlock(13, 17, z, "minecraft:bone_block[axis=y]");

    // Vertebrae nodes with prominent dorsal & transverse spines
    if (z % 6 === 3 || z % 6 === 4) {
      setBlock(13, 18, z, "minecraft:bone_block[axis=y]");
      setBlock(13, 19, z, "minecraft:bone_block[axis=y]");
      setBlock(11, 16, z, "minecraft:bone_block[axis=x]");
      setBlock(15, 16, z, "minecraft:bone_block[axis=x]");
      setBlock(11, 17, z, "minecraft:bone_block[axis=y]");
      setBlock(15, 17, z, "minecraft:bone_block[axis=y]");
    }
  }

  // ==========================================
  // 3. CURVED SKY-WHALE RIB ARCHES
  // ==========================================
  const ribZCenters = [3, 9, 15, 21, 27, 33, 39, 45];

  for (const z0 of ribZCenters) {
    for (let dz = 0; dz <= 1; dz++) {
      const z = z0 + dz;

      // Parametric rib vault curve
      for (let step = 0; step <= 50; step++) {
        const u = step / 50.0; // 0 (bottom) to 1 (apex)
        const y = Math.round(u * 16.0);

        // Organic parabolic catenary with desert whale outward flare
        const xLeftExact = 13.0 - 11.5 * Math.sqrt(Math.max(0, 1 - u * u)) - 1.5 * Math.sin(Math.PI * u);
        const xLeft = Math.round(xLeftExact);
        const xRight = 26 - xLeft;

        const axis = (u > 0.65) ? "axis=x" : "axis=y";
        const bone = `minecraft:bone_block[${axis}]`;

        // Left rib thickness
        setBlock(xLeft, y, z, bone);
        if (u < 0.65) {
          setBlock(xLeft + 1, y, z, bone);
        } else {
          setBlock(xLeft, y - 1, z, bone);
        }

        // Right rib thickness
        setBlock(xRight, y, z, bone);
        if (u < 0.65) {
          setBlock(xRight - 1, y, z, bone);
        } else {
          setBlock(xRight, y - 1, z, bone);
        }
      }
    }

    // Anchor bone footings deep into local terrain
    for (let rx = 1; rx <= 4; rx++) {
      for (let rz = z0 - 1; rz <= z0 + 2; rz++) {
        const h = Math.floor(api.heightAt(rx, rz));
        for (let y = Math.min(0, h); y <= 0; y++) {
          setBlock(rx, y, rz, "minecraft:bone_block[axis=y]");
        }
      }
    }
    for (let rx = 22; rx <= 25; rx++) {
      for (let rz = z0 - 1; rz <= z0 + 2; rz++) {
        const h = Math.floor(api.heightAt(rx, rz));
        for (let y = Math.min(0, h); y <= 0; y++) {
          setBlock(rx, y, rz, "minecraft:bone_block[axis=y]");
        }
      }
    }
  }

  // ==========================================
  // 4. MEZZANINE CATWALKS & ACCESS STAIRS
  // ==========================================
  // Balcony decks
  for (let z = 4; z <= 44; z++) {
    // West catwalk
    for (let x = 4; x <= 6; x++) {
      setBlock(x, 6, z, woodPlanks);
    }
    setBlock(6, 7, z, woodFence);

    // East catwalk
    for (let x = 20; x <= 22; x++) {
      setBlock(x, 6, z, woodPlanks);
    }
    setBlock(20, 7, z, woodFence);
  }

  // Catwalk support pillars at rib junctions
  for (const z0 of ribZCenters) {
    for (let y = 1; y <= 6; y++) {
      setBlock(5, y, z0, woodLog);
      setBlock(21, y, z0, woodLog);
    }
  }

  // Access stairs to catwalks (North and South flights)
  const stairSets = [
    { startZ: 5, dir: 1, facing: "south" },
    { startZ: 43, dir: -1, facing: "north" },
  ];

  for (const set of stairSets) {
    for (let i = 0; i < 5; i++) {
      const curZ = set.startZ + i * set.dir;
      const curY = 1 + i;

      // West flight
      for (let sy = 1; sy < curY; sy++) {
        setBlock(7, sy, curZ, woodPlanks);
      }
      setBlock(7, curY, curZ, withState(woodStairs, `facing=${set.facing},half=bottom`));

      // East flight
      for (let sy = 1; sy < curY; sy++) {
        setBlock(19, sy, curZ, woodPlanks);
      }
      setBlock(19, curY, curZ, withState(woodStairs, `facing=${set.facing},half=bottom`));
    }
  }

  // ==========================================
  // 5. BAZAAR MERCHANT STALLS & COUNTERS
  // ==========================================
  const stallAwnings = [
    ["minecraft:yellow_wool", "minecraft:white_wool"],
    ["minecraft:orange_wool", "minecraft:white_wool"],
    ["minecraft:terracotta", "minecraft:yellow_terracotta"],
    ["minecraft:yellow_wool", "minecraft:orange_wool"],
    ["minecraft:white_wool", "minecraft:smooth_sandstone"],
    ["minecraft:orange_terracotta", "minecraft:yellow_wool"],
    ["minecraft:yellow_wool", "minecraft:white_wool"],
  ];

  for (let k = 0; k < ribZCenters.length - 1; k++) {
    const zStart = ribZCenters[k] + 2;
    const zEnd = ribZCenters[k + 1] - 1;
    const awning = stallAwnings[k % stallAwnings.length];

    for (let z = zStart; z <= zEnd; z++) {
      // West stall trade counters & decor
      setBlock(8, 1, z, woodFence);
      setBlock(8, 2, z, withState(stoneStairs, "facing=east,half=top"));
      setBlock(4, 1, z, (z % 2 === 0) ? "minecraft:barrel[facing=up]" : stoneAccent);
      setBlock(4, 2, z, (z % 2 === 0) ? "minecraft:bookshelf" : "minecraft:hay_block[axis=y]");

      // East stall trade counters & decor
      setBlock(18, 1, z, woodFence);
      setBlock(18, 2, z, withState(stoneStairs, "facing=west,half=top"));
      setBlock(22, 1, z, (z % 2 === 0) ? "minecraft:cauldron" : "minecraft:barrel[facing=up]");
      setBlock(22, 2, z, (z % 2 === 0) ? stoneAccent : "minecraft:bone_block[axis=y]");

      // Stall shade awnings (sloping downward toward street)
      const color = awning[(z - zStart) % 2];

      // West awning
      setBlock(4, 5, z, color);
      setBlock(5, 5, z, color);
      setBlock(6, 5, z, color);
      setBlock(7, 4, z, color);
      setBlock(8, 4, z, color);

      // East awning
      setBlock(22, 5, z, color);
      setBlock(21, 5, z, color);
      setBlock(20, 5, z, color);
      setBlock(19, 4, z, color);
      setBlock(18, 4, z, color);
    }

    // Corner lantern posts on counters
    setBlock(8, 3, zStart, woodFence);
    setBlock(8, 3, zEnd, woodFence);
    setBlock(18, 3, zStart, woodFence);
    setBlock(18, 3, zEnd, woodFence);
  }

  // ==========================================
  // 6. HIGH VAULT SHADE CANOPIES & SUNBEAMS
  // ==========================================
  for (let k = 0; k < ribZCenters.length - 1; k += 2) {
    const zStart = ribZCenters[k] + 2;
    const zEnd = ribZCenters[k + 1] - 1;

    for (let z = zStart; z <= zEnd; z++) {
      for (let x = 9; x <= 17; x++) {
        // Catenary drape across upper nave
        const sag = Math.round(14 - 1.6 * Math.sin(Math.PI * (x - 9) / 8.0));

        // Artistic slits letting dramatic desert sun rays reach the bazaar floor
        if ((x + z) % 4 !== 0) {
          const tarpBlock = ((x + z) % 3 === 0) ? "minecraft:white_wool" : "minecraft:yellow_wool";
          setBlock(x, sag, z, tarpBlock);
        }
      }
    }
  }

  // ==========================================
  // 7. CENTRAL SPINE LIGHTING (Hanging Lanterns)
  // ==========================================
  const chandelierZs = [6, 12, 18, 24, 30, 36, 42];
  for (const cz of chandelierZs) {
    setBlock(13, 15, cz, "minecraft:chain[axis=y]");
    setBlock(13, 14, cz, "minecraft:chain[axis=y]");
    setBlock(13, 13, cz, "minecraft:chain[axis=y]");
    setBlock(13, 12, cz, "minecraft:lantern[hanging=true]");
  }

  // ==========================================
  // 8. GRAND ENTRANCE PORTALS (North & South)
  // ==========================================
  // North Portal (Front - Whale Cervical Collar & Tusks)
  const leftTuskCoords = [
    [6, 1, 1], [5, 2, 1], [5, 3, 1], [4, 4, 1], [4, 5, 1], [3, 6, 1], [3, 7, 0], [2, 8, 0]
  ];
  for (const [tx, ty, tz] of leftTuskCoords) {
    setBlock(tx, ty, tz, "minecraft:bone_block[axis=y]");
  }

  const rightTuskCoords = [
    [20, 1, 1], [21, 2, 1], [21, 3, 1], [22, 4, 1], [22, 5, 1], [23, 6, 1], [23, 7, 0], [24, 8, 0]
  ];
  for (const [tx, ty, tz] of rightTuskCoords) {
    setBlock(tx, ty, tz, "minecraft:bone_block[axis=y]");
  }

  // Entrance ceremonial stone plinths
  setBlock(8, 1, 0, stoneAccent);
  setBlock(8, 2, 0, stoneWall);
  setBlock(8, 3, 0, "minecraft:lantern[hanging=false]");

  setBlock(18, 1, 0, stoneAccent);
  setBlock(18, 2, 0, stoneWall);
  setBlock(18, 3, 0, "minecraft:lantern[hanging=false]");

  // South Exit Portal (Caudal Vertebral Gateway)
  setBlock(8, 1, D - 1, stoneAccent);
  setBlock(8, 2, D - 1, stoneWall);
  setBlock(8, 3, D - 1, "minecraft:lantern[hanging=false]");

  setBlock(18, 1, D - 1, stoneAccent);
  setBlock(18, 2, D - 1, stoneWall);
  setBlock(18, 3, D - 1, "minecraft:lantern[hanging=false]");

  return {
    name: "Skywhale Ribcage Market Arcade",
    seatY: 0,
    anchors: {
      front: [13, 0, 0],
      door: [13, 0, 0],
      back: [13, 0, 47],
      street_north: [13, 0, 0],
      street_south: [13, 0, 47],
    },
    interiors: [
      { min: [9, 1, 2], max: [17, 10, 45], kind: "hall" },
      { min: [4, 1, 4], max: [7, 4, 14], kind: "shop" },
      { min: [4, 1, 16], max: [7, 4, 26], kind: "bazaar" },
      { min: [4, 1, 28], max: [7, 4, 38], kind: "vault" },
      { min: [19, 1, 4], max: [22, 4, 14], kind: "shop" },
      { min: [19, 1, 16], max: [22, 4, 26], kind: "market" },
      { min: [19, 1, 28], max: [22, 4, 38], kind: "shop" },
    ],
  };
}

