export const envelope = [11, 12, 11];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 3;
  const cx = 5;
  const cz = 5;

  const instIdx = api.instance ? api.instance.index : 0;
  const rng = () => api.random();

  // Palette resolution from theme and literal fossil materials
  const boneY = "minecraft:bone_block[axis=y]";
  const boneX = "minecraft:bone_block[axis=x]";
  const boneZ = "minecraft:bone_block[axis=z]";
  const stonePri = api.theme.stone.primary || "minecraft:smooth_sandstone";
  const stoneAcc = api.theme.stone.accent || "minecraft:cut_sandstone";
  const stoneWall = api.theme.stone.wall || "minecraft:sandstone_wall";
  const groundPave = api.theme.ground.pavement || "minecraft:sandstone";
  const groundScree = api.theme.ground.scree || "minecraft:sand";
  const groundBank = api.theme.ground.bank || "minecraft:smooth_sandstone";
  const woodFence = api.theme.wood.fence || "minecraft:oak_fence";

  // 3D Voxel grid
  const grid = [];
  for (let x = 0; x < W; x++) {
    grid[x] = [];
    for (let y = 0; y < H; y++) {
      grid[x][y] = new Array(D).fill(null);
    }
  }

  // --- Procedural Morphology Parameters per Instance ---
  // Morphological types:
  // 0: Majestic tall blade spine, wide sweeping wings, hanging central lantern
  // 1: Tilted forward, fractured stub spine, left wing horn beacon
  // 2: Twin-horned dorsal crest, upward curving wings, roadside cairn
  // 3: Fenestrated (windowed) dorsal crest, compact wings, embedded glowing relic
  const spineType = instIdx % 4;
  const tiltX = (rng() - 0.5) * 0.22; // forward/backward tilt
  const tiltZ = (rng() - 0.5) * 0.16; // lateral lean

  const spineLeanX = (rng() - 0.5) * 0.2;
  const spineLeanZ = (rng() * 0.35) - 0.1; // slight backward or forward sweep
  const spineHeight = spineType === 1 ? 7.0 + rng() * 0.6 : (spineType === 0 ? 8.4 + rng() * 0.5 : 7.8 + rng() * 0.5);
  const spineThickX = spineType === 3 ? 1.35 : (spineType === 0 ? 1.05 : 0.9);
  const spineThickZ = spineType === 3 ? 1.8 : 1.4;

  const leftWingLen = 3.6 + rng() * 1.2;
  const rightWingLen = (instIdx % 3 === 1) ? 2.8 + rng() * 0.6 : 3.6 + rng() * 1.2; // asymmetric erosion
  const leftWingSlope = (rng() - 0.4) * 0.6;
  const rightWingSlope = (rng() - 0.4) * 0.6;
  const leftWingSweep = (rng() - 0.5) * 0.5;
  const rightWingSweep = (rng() - 0.5) * 0.5;
  const wingBaseY = 3.2 + rng() * 0.6;
  const wingThickness = 0.95 + rng() * 0.25;

  const pillarDist = 2.75 + (rng() - 0.5) * 0.3;
  const pillarRadius = 1.75;
  const pillarTopY = 4.9;

  const archCenterY = 2.9;
  const archOuterRad = 3.6;
  const archInnerRad = 1.7;
  const archMinY = 2.5;
  const archMaxY = 6.2;
  const archThicknessZ = 2.2;

  const weatheringChance = 0.18 + rng() * 0.22;

  // --- Geometry Evaluation Function ---
  function evaluateVertebra(x, y, z) {
    const rx = x - cx;
    const ry = y - seatY;
    const rz = z - cz;

    // Apply 3D coordinate tilt
    const tx = rx - tiltZ * ry;
    const ty = ry;
    const tz = rz - tiltX * ry;

    // Road tunnel exclusion (neural canal interior)
    if (Math.abs(tx) < 1.45 && ty >= 0 && ty < 3.7 && Math.abs(tz) <= 4.8) {
      return { solid: false };
    }

    // 1. Pillars (Vertebral Pedicles & Base Columns)
    const leftDist = Math.hypot(tx - (-pillarDist), tz * 0.85);
    const rightDist = Math.hypot(tx - pillarDist, tz * 0.85);
    const pRad = pillarRadius - 0.08 * ty;
    const inLeftPillar = (leftDist <= pRad) && (ty >= 0 && ty <= pillarTopY);
    const inRightPillar = (rightDist <= pRad) && (ty >= 0 && ty <= pillarTopY);

    // 2. Arch Vault (Neural Arch Crest)
    const archRad = Math.hypot(tx, (ty - archCenterY) * 1.15);
    const inArch = (archRad <= archOuterRad) && (archRad >= archInnerRad) &&
                   (ty >= archMinY && ty <= archMaxY) && (Math.abs(tz) <= archThicknessZ);

    // 3. Dorsal Spine (Neural Process)
    let inSpine = false;
    if (ty >= archMaxY - 0.9 && ty <= spineHeight) {
      const sH = ty - (archMaxY - 0.9);
      const spX = tx - spineLeanX * sH;
      const spZ = tz - spineLeanZ * sH;

      if (spineType === 2 && ty > archMaxY + 1.0) {
        // Twin-forked crest
        const dL = Math.hypot(spX - (-0.85), spZ);
        const dR = Math.hypot(spX - 0.85, spZ);
        inSpine = (dL <= 0.8 || dR <= 0.8);
      } else if (spineType === 3 && ty > archMaxY + 0.5 && ty < spineHeight - 0.6 && Math.abs(spZ) < 0.65) {
        // Fenestrated crest (window pierced in bone)
        const distCrest = Math.hypot(spX / spineThickX, spZ / spineThickZ);
        inSpine = distCrest <= 1.0 && (Math.abs(ty - (archMaxY + 1.4)) > 0.55 || Math.abs(spX) > 0.55);
      } else {
        const thickX = Math.max(0.65, spineThickX - 0.08 * sH);
        const thickZ = Math.max(0.7, spineThickZ - 0.12 * sH);
        inSpine = (Math.abs(spX) <= thickX) && (Math.abs(spZ) <= thickZ);
      }
    }

    // 4. Transverse Processes (Lateral Wings)
    let inWings = false;
    if (tx <= -1.7 && tx >= -leftWingLen) {
      const wFrac = (-tx - 1.7) / (leftWingLen - 1.7 + 0.001);
      const wY = wingBaseY + leftWingSlope * wFrac;
      const wZ = leftWingSweep * wFrac;
      const wThick = Math.max(0.6, wingThickness * (1.0 - 0.35 * wFrac));
      if (Math.hypot(ty - wY, tz - wZ) <= wThick) inWings = true;
    }
    if (tx >= 1.7 && tx <= rightWingLen) {
      const wFrac = (tx - 1.7) / (rightWingLen - 1.7 + 0.001);
      const wY = wingBaseY + rightWingSlope * wFrac;
      const wZ = rightWingSweep * wFrac;
      const wThick = Math.max(0.6, wingThickness * (1.0 - 0.35 * wFrac));
      if (Math.hypot(ty - wY, tz - wZ) <= wThick) inWings = true;
    }

    // 5. Articular Facets (Anterior & Posterior Zygapophyses)
    let inFacets = false;
    if (Math.abs(ty - 4.1) <= 1.2) {
      const dPreL = Math.hypot(tx - (-2.1), tz - (-1.8));
      const dPreR = Math.hypot(tx - 2.1, tz - (-1.8));
      const dPostL = Math.hypot(tx - (-2.1), tz - 1.8);
      const dPostR = Math.hypot(tx - 2.1, tz - 1.8);
      if (dPreL <= 0.85 || dPreR <= 0.85 || dPostL <= 0.85 || dPostR <= 0.85) {
        inFacets = true;
      }
    }

    // 6. Centrum Base Collar & Footing Flanges
    let inBaseCollar = false;
    if (ty >= 0 && ty <= 2.2) {
      const bDistL = Math.hypot(tx - (-2.6), tz);
      const bDistR = Math.hypot(tx - 2.6, tz);
      if ((bDistL <= 2.35 - 0.35 * ty || bDistR <= 2.35 - 0.35 * ty) && Math.abs(tx) >= 1.1) {
        inBaseCollar = true;
      }
      // Posterior centrum thick ridge
      if (tz >= 1.2 && tz <= 2.8 && Math.abs(tx) <= 3.2 && Math.abs(tx) >= 1.0) {
        inBaseCollar = true;
      }
    }

    const isSolid = inLeftPillar || inRightPillar || inArch || inSpine || inWings || inFacets || inBaseCollar;
    if (!isSolid) return { solid: false };

    // Select bone striation axis
    let axis = "y";
    if (inWings) {
      axis = "x";
    } else if (inFacets || (inArch && Math.abs(tz) > 1.3)) {
      axis = "z";
    } else if (inArch && ty >= archMaxY - 1.0) {
      axis = "x";
    }

    return {
      solid: true,
      axis,
      inSpine,
      inWings,
      inArch,
      ty
    };
  }

  // --- Step 1: Rasterize Bone Geometry into Grid ---
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const res = evaluateVertebra(x, y, z);
        if (res.solid) {
          // Weathering / mineral crust patina
          const r = rng();
          if (r < weatheringChance * 0.6) {
            grid[x][y][z] = stonePri;
          } else if (r < weatheringChance) {
            grid[x][y][z] = stoneAcc;
          } else {
            grid[x][y][z] = res.axis === "x" ? boneX : (res.axis === "z" ? boneZ : boneY);
          }
        }
      }
    }
  }

  // --- Step 2: Ground Adaptation & Deep Foundation Conformance ---
  // Every column reads api.heightAt and solidly anchors into the terrain
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const h = api.heightAt(x, z);
      const gY = Math.max(0, Math.min(H - 1, seatY + Math.round(h)));

      // Check if structure stands above this column
      let hasStructureAbove = false;
      for (let y = seatY; y < H; y++) {
        if (grid[x][y][z] != null) {
          hasStructureAbove = true;
          break;
        }
      }

      if (hasStructureAbove) {
        // If ground drops below seat plane, fill down to terrain surface
        if (gY < seatY) {
          for (let y = gY; y < seatY; y++) {
            grid[x][y][z] = (y === gY && rng() > 0.5) ? groundBank : boneY;
          }
        }
        // If ground rises above seat plane, thicken foundation courses
        if (gY > seatY) {
          for (let y = seatY; y <= gY; y++) {
            if (grid[x][y][z] == null) {
              grid[x][y][z] = boneY;
            }
          }
        }
      }
    }
  }

  // --- Step 3: Spine Road / Highway Path Through Neural Canal ---
  // Pave the traversable street through the archway
  for (let z = 0; z < D; z++) {
    for (let x = cx - 1; x <= cx + 1; x++) {
      const h = api.heightAt(x, z);
      const gY = Math.max(0, Math.min(H - 4, seatY + Math.round(h)));

      // Road pavement course at terrain level
      const isEdge = (x === cx - 1 || x === cx + 1);
      grid[x][gY][z] = isEdge ? stoneAcc : groundPave;

      // Ensure clear headroom for travelers walking through
      for (let y = gY + 1; y <= gY + 3; y++) {
        if (y < H && grid[x][y][z] != null) {
          // Keep arch vault overhead, clear passage below
          if (y < 6) {
            grid[x][y][z] = null;
          }
        }
      }
    }
  }

  // --- Step 4: Waypoint Marker Details (Differing by Instance) ---
  const waypointKind = instIdx % 4;

  if (waypointKind === 0) {
    // Hanging ancient desert lantern from the arch keystone
    let archCeilY = -1;
    for (let y = 5; y < H; y++) {
      if (grid[cx][y][cz] != null) {
        archCeilY = y;
        break;
      }
    }
    if (archCeilY >= 7) {
      grid[cx][archCeilY - 1][cz] = "minecraft:chain[axis=y]";
      grid[cx][archCeilY - 2][cz] = "minecraft:lantern[hanging=true]";
    }
  } else if (waypointKind === 1) {
    // Beacon on the left transverse wing tip
    let tipX = 0;
    while (tipX < cx && grid[tipX][seatY + 3][cz] == null) {
      tipX++;
    }
    let topY = -1;
    for (let y = H - 1; y >= 0; y--) {
      if (grid[tipX][y][cz] != null) {
        topY = y;
        break;
      }
    }
    if (topY >= seatY && topY < H - 2) {
      grid[tipX][topY + 1][cz] = woodFence;
      grid[tipX][topY + 2][cz] = "minecraft:lantern[hanging=false]";
    }
  } else if (waypointKind === 2) {
    // Roadside cairn waypoint shrine on the eastern approach
    const cairnX = cx + 3;
    const cairnZ = cz - 2;
    const h = api.heightAt(cairnX, cairnZ);
    const gY = Math.max(0, Math.min(H - 4, seatY + Math.round(h)));
    grid[cairnX][gY + 1][cairnZ] = stoneWall;
    grid[cairnX][gY + 2][cairnZ] = stonePri;
    grid[cairnX][gY + 3][cairnZ] = "minecraft:torch";
  } else if (waypointKind === 3) {
    // Embedded glowing relic / amber node in dorsal spine forehead
    for (let y = 7; y <= 9; y++) {
      if (grid[cx][y][cz - 1] != null) {
        grid[cx][y][cz - 1] = "minecraft:ochre_froglight";
        break;
      }
    }
  }

  // --- Step 5: Connectivity Check & Voxel Volume Guarantee ---
  // Ensure >= 500 solid voxels by reinforcing base/scree plinth if needed
  function countSolid() {
    let cnt = 0;
    for (let x = 0; x < W; x++) {
      for (let y = 0; y < H; y++) {
        for (let z = 0; z < D; z++) {
          if (grid[x][y][z] != null) cnt++;
        }
      }
    }
    return cnt;
  }

  let solidCount = countSolid();
  if (solidCount < 530) {
    // Thicken vertebral centrum base and plinth skirts
    for (let x = 1; x < W - 1; x++) {
      for (let z = 2; z < D - 2; z++) {
        if (Math.abs(x - cx) >= 2) {
          const h = api.heightAt(x, z);
          const gY = Math.max(0, Math.min(H - 1, seatY + Math.round(h)));
          for (let y = gY; y <= seatY + 1; y++) {
            if (grid[x][y][z] == null) {
              grid[x][y][z] = (y === gY) ? stonePri : boneY;
            }
          }
        }
      }
    }
  }

  // 6-Connectivity BFS to guarantee a single strictly connected solid
  const visited = new Uint8Array(W * H * D);
  const idx = (x, y, z) => (x * H + y) * D + z;
  const components = [];

  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        if (grid[x][y][z] == null) continue;
        const sId = idx(x, y, z);
        if (visited[sId]) continue;

        const comp = [];
        const queue = [[x, y, z]];
        visited[sId] = 1;

        let head = 0;
        while (head < queue.length) {
          const [qx, qy, qz] = queue[head++];
          comp.push([qx, qy, qz]);

          const neighbors = [
            [qx + 1, qy, qz], [qx - 1, qy, qz],
            [qx, qy + 1, qz], [qx, qy - 1, qz],
            [qx, qy, qz + 1], [qx, qy, qz - 1]
          ];

          for (const [nx, ny, nz] of neighbors) {
            if (nx >= 0 && nx < W && ny >= 0 && ny < H && nz >= 0 && nz < D) {
              const nId = idx(nx, ny, nz);
              if (!visited[nId] && grid[nx][ny][nz] != null) {
                visited[nId] = 1;
                queue.push([nx, ny, nz]);
              }
            }
          }
        }
        components.push(comp);
      }
    }
  }

  // Keep largest component, prune any disconnected fragments
  if (components.length > 1) {
    let largest = components[0];
    for (let i = 1; i < components.length; i++) {
      if (components[i].length > largest.length) {
        largest = components[i];
      }
    }

    const keepSet = new Uint8Array(W * H * D);
    for (const [kx, ky, kz] of largest) {
      keepSet[idx(kx, ky, kz)] = 1;
    }

    for (let x = 0; x < W; x++) {
      for (let y = 0; y < H; y++) {
        for (let z = 0; z < D; z++) {
          if (grid[x][y][z] != null && !keepSet[idx(x, y, z)]) {
            grid[x][y][z] = null;
          }
        }
      }
    }
  }

  // --- Step 6: Write Output Blocks in Deterministic Order ---
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        if (grid[x][y][z] != null) {
          api.set(x, y, z, grid[x][y][z]);
        }
      }
    }
  }

  return {
    name: "fossil_vertebra_arch",
    seatY,
    anchors: {
      front: [cx, seatY, 0],
      waypoint: [cx, seatY + 1, cz],
      path_in: [cx, seatY, D - 1],
      path_out: [cx, seatY, 0]
    }
  };
}
